from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            # A single-color rectangular outline encloses a hole. Fill the hole
            # according to its dimensions: odd-by-odd interiors become 7,
            # otherwise 2.
            border_ok = all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0,c1+1))
            border_ok = border_ok and all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0,r1+1))
            if not border_ok:
                continue
